231:   syncCamera(dt) {
232:     const bobAmt = clamp(this.speed / 7, 0, 1) * (this.grounded ? 1 : 0) * (1 - this.adsAmount * 0.8);
233:     const bx = Math.cos(this.bobPhase) * 0.035 * bobAmt;
234:     const by = Math.abs(Math.sin(this.bobPhase)) * 0.045 * bobAmt;
235:     const shake = this.cameraShake;
236:     const sx = (Math.random() - 0.5) * shake, sy = (Math.random() - 0.5) * shake;
237:     this.camera.position.set(
238:       this.pos.x + bx * Math.cos(this.yaw) + sx,
239:       this.pos.y + this.eyeHeight + by - this.landKick + sy,
240:       this.pos.z - bx * Math.sin(this.yaw)
241:     );
242:     this.camera.rotation.order = 'YXZ';
243:     this.camera.rotation.set(this.pitch + this.recoilPitch, this.yaw + this.recoilYaw, this.recoilRoll);
244:     const baseFov = this.baseFov;
245:     const targetFov = this.aiming ? baseFov / this.def.zoom : baseFov;
246:     if (Math.abs(this.camera.fov - targetFov) > 0.05) {
247:       this.camera.fov = damp(this.camera.fov, targetFov, 18, dt || 0.016);
248:       this.camera.updateProjectionMatrix();
249:     }
250:   }
