258:   updateViewModel(dt) {
259:     if (!this.gunRoot) return;
260:     const target = new THREE.Vector3().copy(this.gunBasePos).lerp(this.gunAdsPos, this.adsAmount);
261:     const sway = clamp(this.speed / 7, 0, 1) * (1 - this.adsAmount * 0.85);
262:     target.x += Math.cos(this.bobPhase) * 0.012 * sway;
263:     target.y += Math.sin(this.bobPhase * 2) * 0.012 * sway;
264:     this.weaponKick = damp(this.weaponKick, 0, 12, dt);
265:     this.weaponRoll = damp(this.weaponRoll, 0, 10, dt);
266:     target.z += this.weaponKick * 0.12;
267:     this.gunRoot.position.lerp(target, 1 - Math.exp(-18 * dt));
268:     this.gunRoot.rotation.x = 0.01 - this.weaponKick * 0.22 + (1 - this.adsAmount) * 0.04;
269:     this.gunRoot.rotation.y = 0.03 * (1 - this.adsAmount);
270:     this.gunRoot.rotation.z = this.weaponRoll;
271:     if (this.reloadTimer > 0) {
272:       const total = this.def.reload;
273:       const k = 1 - this.reloadTimer / total;
274:       const dip = Math.sin(k * Math.PI);
275:       this.gunRoot.position.y -= dip * 0.25;
276:       this.gunRoot.rotation.x -= dip * 0.5;
277:       this.gunRoot.rotation.z += dip * 0.4;
278:     }
279:     if (this.switchTimer > 0) {
280:       const k = this.switchTimer / 0.28;
281:       this.gunRoot.position.y -= k * 0.35;
282:     }
283:   }
