285:   updateWeapon(dt, input) {
286:     const w = this.weapon;
287:     this.fireTimer = Math.max(0, this.fireTimer - dt);
288:     this.switchTimer = Math.max(0, this.switchTimer - dt);
289:     this.spreadHeat = Math.max(0, this.spreadHeat - dt * 2.6);
290:     if (this.reloadTimer > 0) {
291:       this.reloadTimer -= dt;
292:       if (this.reloadTimer <= 0) this.finishReload();
293:       return;
294:     }
295:     if (this.switchTimer > 0) return;
296:     if (this.mode !== 'fps') return;
297:     if (input.firing && this.fireTimer <= 0) {
298:       if (w.def.auto || !this.triggerHeld) {
299:         this.tryFire();
300:       }
301:     }
302:     this.triggerHeld = input.firing;
303:   }
