305:   tryFire() {
306:     const w = this.weapon, def = w.def;
307:     if (!this.alive) return;
308:     if (w.mag <= 0) {
309:       audio.empty();
310:       this.fireTimer = 0.25;
311:       this.game.hud?.flashAmmo();
312:       return;
313:     }
314:     w.mag--;
315:     this.fireTimer = 60 / def.rpm;
316:     this.shots++;
317:     this.weaponKick = 1;
318:     this.weaponRoll = rand(-0.04, 0.04);
319:     this.spreadHeat = clamp(this.spreadHeat + 0.22, 0, 2.6);
320:     const spread = this.currentSpread();
321:     // Soft aim assist for touch. It only nudges pellets already inside a narrow
322:     // cone; solid geometry still blocks the shot in castShot().
323:     let assistDir = null;
324:     if (this.game.input?.isTouch && this.profile.settings.aimAssist !== false && this.game.bots) {
325:       const base = this.camera.getWorldDirection(new THREE.Vector3());
326:       let bestDot = Math.cos(deg(7));
327:       for (const b of this.game.bots.bots) {
328:         if (!b.alive || (this.game.mode.id !== 'br' && b.team === 0)) continue;
329:         const to = b.center().sub(this.camera.position);
330:         const dist = to.length();
331:         if (dist < 3 || dist > 95) continue;
332:         to.multiplyScalar(1 / dist);
333:         const dot = to.dot(base);
334:         if (dot > bestDot) { bestDot = dot; assistDir = to; }
335:       }
336:     }
337:     for (let p = 0; p < def.pellets; p++) {
338:       const dir = this.camera.getWorldDirection(new THREE.Vector3());
339:       const right = new THREE.Vector3().crossVectors(dir, new THREE.Vector3(0, 1, 0)).normalize();
340:       const up = new THREE.Vector3().crossVectors(right, dir).normalize();
341:       const a = rand(0, Math.PI * 2), r = Math.tan(deg(spread)) * Math.sqrt(Math.random());
342:       dir.addScaledVector(right, Math.cos(a) * r).addScaledVector(up, Math.sin(a) * r).normalize();
343:       if (assistDir) dir.lerp(assistDir, this.aiming ? 0.62 : 0.42).normalize();
344:       const origin = this.camera.position.clone();
345:       const hit = this.game.castShot(origin, dir, def.range, this);
346:       const end = hit.point;
347:       const muzzleWorld = this.getMuzzleWorld();
348:       this.game.effects.tracer(muzzleWorld, end, def.id === 'longshot' ? 0xbfe4ff : 0xffc06a);
349:       if (hit.bot) {
350:         const dist = hit.distance;
351:         let dmg = def.dmg;
352:         if (def.pellets > 1) dmg *= clamp(1 - dist / (def.range * 1.2), 0.25, 1);
353:         if (def.falloff && dist > def.falloff[0]) {
354:           const t = clamp((dist - def.falloff[0]) / (def.falloff[1] - def.falloff[0]), 0, 1);
355:           dmg *= lerp(1, def.falloff[2], t);
356:         }
357:         if (hit.zone === 'head') dmg *= 2.1;
358:         else if (hit.zone === 'leg') dmg *= 0.8;
359:         this.hits++;
360:         if (hit.zone === 'head') this.headshots++;
361:         this.game.damageBot(hit.bot, Math.round(dmg), this, hit.point, hit.zone === 'head', def);
362:         this.game.effects.impact(hit.point, hit.normal, '#ffca7a', true);
363:         audio.hit(hit.zone === 'head');
364:       } else {
365:         this.game.effects.impact(hit.point, hit.normal, '#ffd08a', false);
366:       }
367:     }
368:     this.recoilPitch += deg(def.recoil * 0.32) * (1 - this.adsAmount * 0.38);
369:     this.recoilYaw += rand(-1, 1) * deg(def.recoil * 0.1) * (1 - this.adsAmount * 0.5);
370:     this.recoilRoll += rand(-1, 1) * deg(0.35);
371:     this.cameraShake = Math.max(this.cameraShake, def.recoil * 0.006);
372:     const muzzleWorld = this.getMuzzleWorld();
373:     this.game.effects.muzzle(muzzleWorld, '#ffd08a', def.pellets > 5 ? 1.6 : 1);
374:     audio.shot(def.model, 0);
375:     this.game.onShot?.();
376:     if (w.mag === 0) this.startReload();
377:     this.game.hud?.updateAmmo();
378:   }
