380:   currentSpread() {
381:     const def = this.def;
382:     let s = def.spread;
383:     const move = clamp(this.speed / 7, 0, 1);
384:     s += move * (def.moveSpread || 1) * 2.2;
385:     s += this.spreadHeat * 0.55;
386:     if (this.aiming) s = lerp(s, def.adsSpread, this.adsAmount) * 0.5;
387:     if (this.crouching) s *= 0.72;
388:     return s;
389:   }
390: 
391:   getMuzzleWorld() {
392:     const forward = this.camera.getWorldDirection(new THREE.Vector3());
393:     const right = new THREE.Vector3().crossVectors(forward, new THREE.Vector3(0, 1, 0)).normalize();
394:     return this.camera.position.clone().addScaledVector(forward, 0.75 + this.adsAmount * 0.2).addScaledVector(right, 0.18 * (1 - this.adsAmount)).add(new THREE.Vector3(0, -0.1, 0));
395:   }
