397:   startReload() {
398:     const w = this.weapon, def = w.def;
399:     if (this.reloadTimer > 0 || w.mag >= def.mag || w.reserve <= 0) return;
400:     this.reloadTimer = def.reload;
401:     audio.reload();
402:     this.game.hud?.startReload(def.reload);
