405:     const w = this.weapon, def = w.def;
406:     const need = def.mag - w.mag;
407:     const take = this.game.mode.infiniteAmmo ? need : Math.min(need, w.reserve);
408:     w.mag += take;
409:     if (!this.game.mode.infiniteAmmo) w.reserve -= take;
410:     this.game.hud?.updateAmmo();
411:   }
