430:       for (let k = 0; k < 6; k++) {
431:         if (!this.world.isSolidAt(x, z, this.world.heightAt(x, z) + 1)) { ok = true; break; }
432:         x += rand(-4, 4); z += rand(-4, 4);
433:       }
434:       if (!ok) continue;
435:       const type = Math.random() > 0.65 ? 'truck' : 'buggy';
436:       const color = pick(['#c8652a', '#4b6b48', '#6b4a3a', '#3d5b6b', '#8a7a45']);
437:       const model = createVehicle(type, color);
438:       const gy = this.world.heightAt(x, z);
439:       model.position.set(x, gy + 0.1, z);
440:       model.rotation.y = s.yaw;
441:       this.scene.add(model);
442:       this.vehicles.push({
443:         model, pos: new THREE.Vector3(x, gy + 0.1, z), yaw: s.yaw, speed: 0,
444:         health: 100, wheels: model.userData.wheels, type, destroyed: false, lastHit: -10
445:       });
446:     }
447:   }
