449:   nearestVehicle(maxDist = 4) {
450:     let best = null, bd = maxDist;
451:     for (const v of this.vehicles) {
452:       if (v.destroyed) continue;
453:       const d = Math.hypot(v.pos.x - this.player.pos.x, v.pos.z - this.player.pos.z);
454:       if (d < bd) { bd = d; best = v; }
455:     }
456:     return best;
457:   }
