479:     this.player.pos.set(v.pos.x + side.x, this.world.heightAt(v.pos.x + side.x, v.pos.z + side.z) + 0.05, v.pos.z + side.z);
480:     this.world.collide(this.player.pos, 0.4, this.player.pos.y);
