495:   updateVehicle(dt) {
496:     const v = this.vehicle;
497:     if (!v) return;
498:     const throttle = this.input.forward;
499:     const steer = this.input.strafe;
500:     const maxF = v.type === 'truck' ? 19 : 26;
501:     const target = throttle * (throttle >= 0 ? maxF : -8);
502:     v.speed = damp(v.speed, target, throttle ? 1.8 : 2.6, dt);
503:     if (Math.abs(v.speed) < 0.03) v.speed = 0;
504:     const steerAmt = clamp(Math.abs(v.speed) / 12, 0, 1.3);
505:     v.yaw -= steer * steerAmt * 1.45 * Math.sign(v.speed || 1) * dt;
506:     const fx = -Math.sin(v.yaw), fz = -Math.cos(v.yaw);
507:     const oldX = v.pos.x, oldZ = v.pos.z;
508:     v.pos.x += fx * v.speed * dt;
509:     v.pos.z += fz * v.speed * dt;
510:     this.world.collide(v.pos, 1.35, v.pos.y);
511:     const bump = Math.hypot(v.pos.x - oldX, v.pos.z - oldZ) < Math.abs(v.speed * dt) * 0.5;
512:     if (bump) {
513:       if (Math.abs(v.speed) > 10) { v.health -= Math.abs(v.speed) * 0.7; this.effects.impact(new THREE.Vector3(v.pos.x, v.pos.y + 1, v.pos.z), null, '#ffce7a', false); audio.land(); this.player.cameraShake = 0.04; }
514:       v.speed *= -0.22;
515:     }
516:     const gy = this.world.heightAt(v.pos.x, v.pos.z);
517:     v.pos.y = gy + 0.1;
518:     // tilt to terrain
519:     const fh = this.world.heightAt(v.pos.x + fx * 1.6, v.pos.z + fz * 1.6);
520:     const bh = this.world.heightAt(v.pos.x - fx * 1.6, v.pos.z - fz * 1.6);
521:     const rh = this.world.heightAt(v.pos.x + Math.cos(v.yaw) * 1.1, v.pos.z - Math.sin(v.yaw) * 1.1);
522:     const lh = this.world.heightAt(v.pos.x - Math.cos(v.yaw) * 1.1, v.pos.z + Math.sin(v.yaw) * 1.1);
523:     const pitch = Math.atan2(fh - bh, 3.2);
524:     const roll = Math.atan2(lh - rh, 2.2);
525:     v.model.position.copy(v.pos);
526:     v.model.rotation.order = 'YXZ';
527:     v.model.rotation.y = v.yaw;
528:     v.model.rotation.x = damp(v.model.rotation.x, -pitch, 6, dt);
529:     v.model.rotation.z = damp(v.model.rotation.z, roll, 6, dt);
530:     for (const w of v.wheels) w.rotation.x += v.speed * dt * 1.4;
531:     this.player.pos.set(v.pos.x, v.pos.y, v.pos.z);
532:     this.player.yaw = v.yaw;
533:     // camera
534:     const camTarget = new THREE.Vector3(v.pos.x - fx * 7.4 + Math.cos(v.yaw) * 0.0, v.pos.y + 3.7, v.pos.z - fz * 7.4);
535:     this.camera.position.lerp(camTarget, 1 - Math.exp(-6 * dt));
536:     const look = new THREE.Vector3(v.pos.x + fx * 3.5, v.pos.y + 1.35, v.pos.z + fz * 3.5);
537:     this.camera.lookAt(look);
538:     this.camera.rotation.z += roll * 0.3;
539:     this.camera.fov = damp(this.camera.fov, (this.profile.settings.fov || 74) + 6, 4, dt);
540:     this.camera.updateProjectionMatrix();
541:     audio.engineSpeed(Math.abs(v.speed));
542:     // run over bots
543:     if (Math.abs(v.speed) > 5) {
544:       for (const b of this.bots.bots) {
545:         if (!b.alive) continue;
546:         if (Math.hypot(b.pos.x - v.pos.x, b.pos.z - v.pos.z) < 2.4 && this.time - b.lastDamage > 0.5) {
547:           b.takeDamage(100, this.player, null, false, null);
548:           this.effects.impact(new THREE.Vector3(b.pos.x, b.pos.y + 1, b.pos.z), null, '#ff9a6a', true);
549:           this.player.kills++;
550:         }
551:       }
552:     }
553:     if (v.health <= 0) {
554:       v.destroyed = true;
555:       this.effects.explosion(new THREE.Vector3(v.pos.x, v.pos.y + 1, v.pos.z), 1.6);
556:       audio.explosion?.();
557:       this.scene.remove(v.model);
558:       this.player.takeDamage(28, null);
559:       this.exitVehicle(true);
560:       this.hud.toast('VEHICLE DESTROYED', 'BAILED OUT');
561:     }
562:   }
