570:   /* ---------------- combat ---------------- */
571:   castShot(origin, dir, range, shooter) {
572:     const raycaster = new THREE.Raycaster(origin, dir, 0.1, range);
573:     const meshes = [];
574:     for (const b of this.bots.bots) if (b.alive && b.hitMeshes) meshes.push(...b.hitMeshes);
575:     const hits = raycaster.intersectObjects(meshes, false);
576:     let wallDist = this.world.rayBlock(origin, dir, range);
577:     // terrain via marching
578:     let terrainDist = range;
579:     const step = 2;
580:     const p = new THREE.Vector3();
581:     for (let d = step; d < Math.min(range, wallDist); d += step) {
582:       p.copy(origin).addScaledVector(dir, d);
583:       if (p.y <= this.world.heightAt(p.x, p.z)) { terrainDist = d; break; }
584:     }
585:     let botHit = null, zone = null, botDist = Infinity;
586:     for (const h of hits) {
587:       if (h.distance >= wallDist || h.distance >= terrainDist) continue;
588:       const bot = h.object.userData.bot;
589:       if (!bot || !bot.alive) continue;
590:       if (bot === shooter) continue;
591:       if (shooter && shooter !== this.player && shooter.team === bot.team) continue;
592:       botDist = h.distance; botHit = bot; zone = h.object.userData.hitZone;
593:       break;
594:     }
595:     const dist = Math.min(range, wallDist, terrainDist, botDist);
596:     const point = origin.clone().addScaledVector(dir, dist);
597:     return { point, bot: botHit, zone, distance: dist, normal: dir.clone().negate() };
598:   }
