602:     const was = bot.alive;
603:     bot.takeDamage(amount, shooter, point, head, def);
604:     this.player.damageDealt += amount;
605:     this.hud.hitmarker(head);
606:     if (was && !bot.alive) {
607:       this.effects.damageNumber(point, amount, head, true);
608:     } else {
609:       this.effects.damageNumber(point, amount, head, false);
610:     }
611:     this.hud.updateAlive();
612:     this.checkEnd();
613:   }
