708:       time, accuracy, mapName: this.map.name, headshots: this.player.headshots,
709:       teamScores: this.bots.teamScores,
710:       coins: Math.round(120 + kills * 45 + (win ? 300 : 0) + placement * 3),
711:       xp: Math.round(180 + kills * 80 + (win ? 600 : 0) + this.player.damageDealt * 0.35),
712:       rankPts: Math.max(-15, kills * 6 + (win ? 40 : 0) - placement)
713:     };
714:     this.matchData = data;
715:     this.app.applyResult(data);
716:     setTimeout(() => {
