742:   /* ---------------- camera / drop ---------------- */
743:   updateCameraDrop(dt) {
744:     const p = this.player, cam = this.camera;
745:     const alt = p.pos.y - this.world.heightAt(p.pos.x, p.pos.z);
746:     const chute = alt < 55;
747:     if (this.parachute) this.parachute.visible = chute;
748:     if (this.playerModel) {
749:       this.playerModel.position.copy(p.pos);
750:       this.playerModel.rotation.y = p.yaw;
751:       if (!chute) {
752:         this.playerModel.rotation.x = damp(this.playerModel.rotation.x, -0.25, 2, dt);
753:       } else {
754:         this.playerModel.rotation.x = damp(this.playerModel.rotation.x, 0.05, 3, dt);
755:       }
756:     }
757:     const fwd = new THREE.Vector3(-Math.sin(p.yaw), 0, -Math.cos(p.yaw));
758:     const camPos = p.pos.clone().addScaledVector(fwd, -7.5).add(new THREE.Vector3(0, chute ? 3.4 : 2.4, 0));
759:     cam.position.lerp(camPos, 1 - Math.exp(-6 * dt));
760:     const look = p.pos.clone().addScaledVector(fwd, 6).add(new THREE.Vector3(0, 1.2, 0));
761:     cam.lookAt(look);
762:     if (chute) cam.rotation.z = Math.sin(this.time * 0.8) * 0.015;
763:     cam.fov = damp(cam.fov, (this.profile.settings.fov || 74) + (chute ? 4 : 10), 3, dt);
764:     cam.updateProjectionMatrix();
765:     this.world.update(dt, p.pos);
766:   }
