768:   landDrop() {
769:     if (this.dropDone) return;
770:     const clear = this.findClearNear(this.player.pos.x, this.player.pos.z, 22);
771:     if (clear.x !== this.player.pos.x || clear.z !== this.player.pos.z) {
772:       this.player.pos.x = clear.x;
773:       this.player.pos.z = clear.z;
774:     }
775:     const gy = this.world.heightAt(this.player.pos.x, this.player.pos.z);
776:     this.player.pos.y = gy + 0.05;
777:     this.player.mode = 'fps';
778:     this.player.eyeHeight = 1.62;
779:     this.dropDone = true;
780:     this.phase = 'play';
781:     this.playerModel.visible = false;
782:     if (this.parachute) this.parachute.visible = false;
783:     this.player.syncCamera(0.016);
784:     this.player.buildViewModel();
785:     this.input.setEnabled(true);
786:     this.hud.hideDrop();
787:     this.hud.root.classList.remove('dropping');
788:     this.hud.root.classList.add('grounded');
789:     if (!this.input.isTouch) this.app.showLockHint?.();
790:     this.hud.banner('DROP COMPLETE', this.target ? this.target.name : this.map.name, 2200);
791:     this.effects.impact(new THREE.Vector3(this.player.pos.x, this.player.pos.y + 0.1, this.player.pos.z), null, '#e8d9b8', false);
792:     this.effects.smoke(new THREE.Vector3(this.player.pos.x, this.player.pos.y + 0.3, this.player.pos.z), '#d9cbb0', 0.28, 1.6, 1.2);
793:     audio.land();
794:     this.camera.fov = this.player.baseFov;
795:     this.camera.updateProjectionMatrix();
796:     this.matchTime = 0;
797:     this.checkEnd();
798:   }
