800:   updateDrop(dt) {
801:     const p = this.player;
802:     const look = this.input.consumeLook();
803:     p.yaw -= look.dx * (this.input.isTouch ? 0.0045 : 0.0022) * (this.profile.settings.sens || 1);
804:     p.pitch = clamp(p.pitch - look.dy * (this.input.isTouch ? 0.004 : 0.002), -0.9, 0.6);
805:     const alt = p.pos.y - this.world.heightAt(p.pos.x, p.pos.z);
806:     const chute = alt < 55;
807:     const steerSpeed = chute ? 9 : 15;
808:     const f = this.input.forward, s = this.input.strafe;
809:     if (this.introTimer <= 0) {
810:       const sin = Math.sin(p.yaw), cos = Math.cos(p.yaw);
811:       const vx = (-sin * f + cos * s) * steerSpeed;
812:       const vz = (-cos * f - sin * s) * steerSpeed;
813:       p.pos.x = clamp(p.pos.x + vx * dt, -280, 280);
814:       p.pos.z = clamp(p.pos.z + vz * dt, -280, 280);
815:     }
816:     const gy = this.world.heightAt(p.pos.x, p.pos.z);
817:     const descent = chute ? 6.5 : (this.input.keys.has('ShiftLeft') ? 34 : 21);
818:     p.pos.y -= descent * dt;
819:     if (p.pos.y <= Math.max(gy + 0.4, this.world.sea + 0.2)) {
820:       this.landDrop();
821:       return;
822:     }
823:     this.updateCameraDrop(dt);
824:     if (this.phase === 'drop') {
825:       const altNow = p.pos.y - gy;
826:       this.hud.updateDrop(1 - altNow / DROP_ALT, altNow, chute);
827:     }
828:   }
