830:   /* ---------------- main update ---------------- */
831:   update(dt) {
832:     if (!this.active) return;
833:     this.time += dt;
834:     if (this.paused) { this.effects.update(dt); return; }
835:     if (!this.over && this.dropDone) this.matchTime += dt;
836: 
837:     if (this.phase === 'intro') {
838:       this.introTimer -= dt;
839:       if (this.mode.id === 'br') {
840:         this.updateDrop(dt);
841:         if (this.introTimer <= 0) {
842:           this.phase = 'drop';
843:           this.input.setEnabled(true);
844:           this.hud.showDrop(this.world, this.mode);
845:         }
846:       } else {
847:         if (this.introTimer <= 0) this.beginGroundMatch();
848:       }
849:     } else if (this.phase === 'drop') {
850:       this.updateDrop(dt);
851:     } else if (this.dropDone) {
852:       if (this.player.alive) {
853:         if (this.vehicle) {
854:           this.updateVehicle(dt);
855:           this.player.fireTimer = Math.max(0, this.player.fireTimer - dt);
856:           this.player.viewGroup.visible = false;
857:         } else {
858:           this.player.update(dt, this.input);
859:         }
860:       } else {
861:         this.deathTimer += dt;
862:         this.player.updateCameraShake(dt);
863:         if (this.mode.respawn && this.respawnTimer > 0) {
864:           this.respawnTimer -= dt;
865:           if (this.respawnTimer <= 0) this.respawnPlayer();
866:         }
867:       }
868:       if (this.bots) {
869:         this.bots.update(dt);
