396:       this.qualityKey = this.resolveQuality(this.profile.settings.quality);
397:       this.game = new Game({
398:         renderer: this.renderer,
399:         profile: this.profile,
400:         map,
401:         mode,
402:         hud: this.hud,
403:         input: this.input,
404:         quality: this.qualityKey,
405:         startMatch: this.startMatch.bind(this),
406:         endGame: this.endGame.bind(this),
407:         applyResult: this.applyResult.bind(this),
408:         openSettings: this.openSettings.bind(this),
409:         setGame: game => { this.game = game; }
410:       });
411: 
412:       this.setMatchLoading(0.86, 'DEPLOYING OPERATOR');
413:       await this.delay(180);
414:       this.setMatchLoading(1, 'MATCH LIVE');
415:       await this.delay(110);
416:       this.hideLoading();
417:       this.starting = false;
418:     } catch (err) {
419:       console.error('[BLAZE] Failed to start match:', err);
420:       this.starting = false;
421:       this.hideLoading();
422:       if (this.game) { try { this.game.dispose(); } catch {} this.game = null; }
423:       $('#lobby').classList.remove('hidden');
424:       this.renderer.domElement.classList.remove('in-game');
425:       this.toast('DEPLOYMENT FAILED', 'CHECK THE CONSOLE AND TRY AGAIN');
