182:     let chance = clamp(0.8 - dist * 0.009 - targetVel * 0.026, 0.1, 0.75) * this.skill;
183:     if (target.crouching) chance *= 0.8;
184:     if (target.aiming) chance *= 0.92;
185:     const hit = Math.random() < chance;
186:     const end = hit ? targetPos.clone() : targetPos.clone().add(new THREE.Vector3(rand(-1.6, 1.6), rand(-0.8, 1.2), rand(-1.6, 1.6)));
187:     this.game.effects.tracer(muzzle, end, 0xffb066);
