193:       if (target === this.game.player) target.takeDamage(Math.round(dmg), this);
194:       else target.takeDamage(Math.round(dmg), this);
195:       this.game.effects.impact(end, null, '#ffb060', true);
196:     } else {
197:       this.game.effects.impact(end, null, '#ffd08a', false);
198:     }
