202:   update(dt) {
203:     if (!this.alive) {
204:       // death animation & cleanup
205:       if (this.model) {
206:         const k = clamp((this.game.time - this.deadTime) / 0.6, 0, 1);
207:         this.model.rotation.z = this.fallDir * k * Math.PI * 0.48;
208:         this.model.position.y = this.pos.y + Math.sin(k * Math.PI) * 0.15 - Math.max(0, (this.game.time - this.deadTime - 5)) * 0.4;
209:         if (this.game.time - this.deadTime > 7.5) { this.remove(); }
210:       }
211:       return;
212:     }
213:     this.prevPos.copy(this.pos);
214:     const now = this.game.time;
215:     this.targetTimer -= dt;
216:     this.fireTimer -= dt;
217: 
218:     // target acquisition
219:     if (this.targetTimer <= 0) {
220:       this.targetTimer = 0.32 + Math.random() * 0.28;
221:       this.target = this.mgr.findTarget(this);
222:       this.state = this.target ? 'attack' : 'patrol';
223:       if (!this.target) this.pickDestination();
224:     }
225:     if (this.target && (!this.target.alive)) this.target = null;
226: 
227:     let moveX = 0, moveZ = 0;
228:     let faceYaw = this.yaw;
229:     if (this.target) {
230:       const tp = this.target.center ? this.target.center() : this.target.pos.clone().add(new THREE.Vector3(0, 1.1, 0));
231:       const dx = tp.x - this.pos.x, dz = tp.z - this.pos.z;
232:       const dist = Math.hypot(dx, dz);
233:       faceYaw = Math.atan2(-dx, -dz);
234:       const ideal = this.weaponDef.model === 'shotgun' ? 9 : this.weaponDef.model === 'sniper' ? 45 : this.weaponDef.model === 'smg' ? 15 : 24;
235:       let forward = 0;
236:       if (dist > ideal + 4) forward = 1;
237:       else if (dist < ideal - 5) forward = -0.7;
238:       const strafe = this.strafeDir;
239:       if (Math.random() < 0.006) this.strafeDir *= -1;
240:       const nx = dx / (dist || 1), nz = dz / (dist || 1);
241:       moveX = (nx * forward + -nz * strafe * 0.72) * this.speed;
242:       moveZ = (nz * forward + nx * strafe * 0.72) * this.speed;
243:       // shooting
244:       if (this.fireTimer <= 0 && dist < 75) {
245:         const eye = this.eye(), targetEye = this.target.eye ? this.target.eye() : this.target.pos.clone().add(new THREE.Vector3(0, 1.2, 0));
246:         const dir = targetEye.clone().sub(eye); const d = dir.length(); dir.normalize();
247:         const blocked = this.world.rayBlock(eye, dir, d);
248:         if (blocked >= d - 1.2) {
249:           this.fireTimer = 60 / this.weaponDef.rpm * rand(1.6, 3.2) + 0.15;
250:           this.fireAt(this.target);
251:           // burst
252:           if (this.weaponDef.auto && Math.random() > 0.35) {
253:             const self = this;
254:             setTimeout(() => { if (self.alive && self.target && self.target.alive) self.fireAt(self.target); }, 110);
255:           }
256:         } else {
257:           this.fireTimer = 0.5;
258:         }
259:       }
260:     } else {
261:       // patrol
262:       const dx = this.dest.x - this.pos.x, dz = this.dest.z - this.pos.z;
263:       const dist = Math.hypot(dx, dz);
264:       if (dist < 2.5) this.pickDestination();
265:       else {
266:         moveX = dx / dist * this.speed * 0.55;
267:         moveZ = dz / dist * this.speed * 0.55;
268:         faceYaw = Math.atan2(-dx, -dz);
269:       }
270:     }
271:     // avoid water
272:     if (this.world.heightAt(this.pos.x, this.pos.z) < 0.3) {
273:       moveX += (0 - this.pos.x) * 0.03; moveZ += (0 - this.pos.z) * 0.03;
274:     }
275:     this.vel.x = damp(this.vel.x, moveX, 8, dt);
276:     this.vel.z = damp(this.vel.z, moveZ, 8, dt);
277:     this.vel.y -= 20 * dt;
278:     this.pos.x += this.vel.x * dt;
279:     this.pos.z += this.vel.z * dt;
280:     this.world.collide(this.pos, 0.42, this.pos.y);
281:     this.pos.y += this.vel.y * dt;
282:     const gy = Math.max(this.world.heightAt(this.pos.x, this.pos.z), this.world.sea - 0.8);
283:     if (this.pos.y <= gy) { this.pos.y = gy; this.vel.y = 0; }
284:     // stuck check
285:     const moved = Math.hypot(this.pos.x - this.prevPos.x, this.pos.z - this.prevPos.z);
286:     if (moved < 0.002 && (this.vel.x || this.vel.z)) {
287:       this.stuckTimer += dt;
288:       if (this.stuckTimer > 1.2) { this.stuckTimer = 0; this.pickDestination(); this.strafeDir *= -1; this.pos.x += rand(-1, 1); this.pos.z += rand(-1, 1); }
289:     } else this.stuckTimer = 0;
290: 
291:     // face target smoothly
292:     this.yaw += angleDelta(this.yaw, faceYaw) * Math.min(1, dt * 7);
293:     this.model.position.copy(this.pos);
294:     this.model.rotation.y = this.yaw;
295:     this.model.rotation.z = damp(this.model.rotation.z, 0, 8, dt);
296:     // walk animation
297:     const spd = Math.hypot(this.vel.x, this.vel.z);
298:     this.walkPhase += dt * spd * 2.1;
299:     const swing = Math.min(1, spd / 3) * 0.55;
300:     this.parts.leftLeg.rotation.x = Math.sin(this.walkPhase) * swing;
301:     this.parts.rightLeg.rotation.x = -Math.sin(this.walkPhase) * swing;
302:     this.parts.leftArm.rotation.x = -1.32 + Math.sin(this.walkPhase) * swing * 0.18;
303:     this.parts.rightArm.rotation.x = -1.18 - Math.sin(this.walkPhase) * swing * 0.1;
304:     this.parts.torso.position.y = 1.2 + Math.abs(Math.sin(this.walkPhase)) * 0.018 * Math.min(1, spd);
305:     this.model.updateMatrixWorld();
306:     // tag visibility
307:     const distToPlayer = this.pos.distanceTo(this.game.player.pos);
308:     if (this.tag) {
309:       this.tag.visible = distToPlayer < 55 || (this.game.time - this.lastDamage < 6);
310:       this.tag.material.opacity = clamp(1.8 - distToPlayer / 45, 0.25, 1);
311:     }
312:     if (this.ring) this.ring.visible = distToPlayer < 70;
313:     // health tag refresh
314:     if (this.tagTimer < this.game.time && this.tag && this.tag.userData.lastHealth !== this.health) {
315:       this.tagTimer = this.game.time + 0.25;
316:       this.updateTag();
317:     }
318:   }
319: 
320:   pickDestination() {
321:     const nearPoi = this.mgr.poiCenters[randInt(0, this.mgr.poiCenters.length - 1)];
322:     if (Math.random() > 0.35 && nearPoi) {
323:       const a = rand(0, Math.PI * 2), r = rand(4, nearPoi.r * 0.9);
324:       this.dest.set(nearPoi.x + Math.cos(a) * r, 0, nearPoi.z + Math.sin(a) * r);
325:     } else {
326:       this.dest.set(this.pos.x + rand(-24, 24), 0, this.pos.z + rand(-24, 24));
327:     }
328:   }
