330:   remove() {
331:     if (this.model) {
332:       this.game.scene.remove(this.model);
333:       this.model.traverse(o => { if (o.isMesh) o.geometry?.dispose?.(); });
334:       this.model = null;
335:     }
336:     this.mgr.remove(this);
337:   }
