396:       return { x: g.player.pos.x + rand(-9, 9), z: g.player.pos.z + rand(-9, 9) };
397:     }
398:     if (team === 1) {
399:       let best = null, bestScore = -1;
400:       for (let i = 0; i < 12; i++) {
401:         const sp = pick(this.world.spawnPoints);
402:         if (!sp) break;
403:         const d = Math.hypot(sp.x - g.player.pos.x, sp.z - g.player.pos.z);
404:         const score = Math.min(120, Math.abs(d - 45)) + rand(0, 15);
405:         if (bestScore < 0 || score < bestScore) { bestScore = score; best = sp; }
406:       }
407:       if (best) return best;
408:     }
409:     // random far from player for BR
410:     for (let i = 0; i < 16; i++) {
411:       const sp = pick(this.world.spawnPoints);
412:       if (!sp) break;
413:       const d = Math.hypot(sp.x - g.player.pos.x, sp.z - g.player.pos.z);
