419:   findTarget(bot) {
420:     const g = this.game;
421:     const candidates = [];
422:     const player = g.player;
423:     if (player.alive && (this.mode.id !== 'tdm' || bot.team !== 0)) {
424:       const d = bot.pos.distanceTo(player.pos);
425:       if (d < 68) candidates.push({ t: player, d });
