427:     for (const b of this.bots) {
428:       if (b === bot || !b.alive) continue;
429:       if (b.team === bot.team) continue;
430:       if (this.mode.id !== 'br' && b.team === bot.team) continue;
431:       const d = bot.pos.distanceTo(b.pos);
432:       if (d < 55) candidates.push({ t: b, d: d * 1.25 });
433:     }
434:     if (!candidates.length) return null;
435:     candidates.sort((a, b) => a.d - b.d);
436:     for (const c of candidates.slice(0, 3)) {
