.drop-target{position:absolute;left:24px;bottom:calc(22% + var(--safe-b));display:flex;align-items:center;gap:7px;font-size:9px;letter-spacing:.16em;color:#dbe5ec;background:rgba(7,10,14,.6);padding:6px 10px;border-left:2px solid var(--orange)}
.drop-target .icon{width:14px;height:14px;color:var(--orange)}

#match-intro{position:absolute;inset:0;z-index:60;display:grid;place-items:center;pointer-events:none}
.mi-bg{position:absolute;inset:0;background:radial-gradient(ellipse at center,rgba(8,12,17,.82),rgba(3,5,8,.96));animation:introBg 2.6s ease forwards}
.mi-content{position:relative;text-align:center;animation:introContent 2.6s ease forwards}
.mi-kicker{font-size:9px;letter-spacing:.5em;color:var(--orange);display:block;margin-bottom:7px}
.mi-content h2{font-size:44px;font-style:italic;letter-spacing:.07em;line-height:1}
.mi-map{font-size:11px;letter-spacing:.4em;color:#bdc9d3;margin:10px 0 20px}
.mi-grid{display:flex;justify-content:center;gap:30px;margin-bottom:22px}
.mi-grid div{display:flex;flex-direction:column;gap:2px}
.mi-grid b{font-family:var(--num);font-size:22px;color:#fff}
.mi-grid span{font-size:6px;letter-spacing:.2em;color:var(--muted)}
.mi-loading{width:180px;height:2px;background:rgba(255,255,255,.15);margin:0 auto;overflow:hidden}
.mi-loading i{display:block;height:100%;width:0;background:var(--orange);animation:introLoad 2.4s ease forwards}
@keyframes introContent{0%{opacity:0;transform:translateY(10px)}15%,78%{opacity:1;transform:none}100%{opacity:0;transform:scale(1.03)}}
@keyframes introBg{0%,80%{opacity:1}100%{opacity:0}}
@keyframes introLoad{0%{width:0}70%,100%{width:100%}}

#scoreboard{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:min(520px,92vw);background:rgba(7,11,16,.92);border:1px solid var(--line);backdrop-filter:blur(14px);z-index:40;pointer-events:auto;box-shadow:0 30px 80px rgba(0,0,0,.6);animation:paneIn .2s ease}
.sb-head{display:flex;justify-content:space-between;align-items:baseline;padding:12px 14px;border-bottom:1px solid var(--line)}
.sb-head h3{font-size:15px;font-style:italic;letter-spacing:.1em}
.sb-head span{font-size:7px;letter-spacing:.17em;color:var(--orange)}
.sb-cols,.sb-row{display:grid;grid-template-columns:32px 1fr 56px 56px;align-items:center;padding:6px 14px;font-size:8px;letter-spacing:.11em}
.sb-cols{color:var(--muted-2);font-size:6px;border-bottom:1px solid rgba(255,255,255,.05)}
.sb-row{border-bottom:1px solid rgba(255,255,255,.035)}
.sb-row.me{background:rgba(255,122,26,.12);color:#fff}
.sb-row .sb-name{display:flex;align-items:center;gap:6px}
.sb-row .sb-dot{width:5px;height:5px;border-radius:50%;background:var(--red)}
.sb-row.me .sb-dot{background:var(--orange)}
.sb-row b{font-family:var(--num);font-size:11px}
.sb-foot{padding:8px 14px;font-size:6px;letter-spacing:.17em;color:var(--muted-2);text-align:center}

#pause{position:absolute;inset:0;background:rgba(3,5,8,.65);backdrop-filter:blur(6px);display:grid;place-items:center;z-index:50;pointer-events:auto}
.pause-card{width:min(320px,88vw);padding:20px}
.pause-tip{font-size:6px;letter-spacing:.12em;color:var(--muted-2);text-align:center;margin-top:8px;line-height:1.8}
#fps-hud{position:absolute;right:18px;bottom:calc(96px + var(--safe-b));font-family:var(--num);font-size:9px;color:rgba(255,255,255,.45);letter-spacing:.08em;display:none}
#fps-hud.show{display:block}

/* Touch UI */
#touch-ui{position:absolute;inset:0;pointer-events:none;z-index:15}
#look-zone{position:absolute;inset:0;pointer-events:none;touch-action:none;z-index:1}
body.touch #look-zone{pointer-events:auto}
#stick-zone{position:absolute;left:0;bottom:0;width:44%;height:58%;pointer-events:auto;touch-action:none;z-index:3}
.stick-base{position:absolute;width:114px;height:114px;border-radius:50%;border:1px solid rgba(255,255,255,.22);background:radial-gradient(circle,rgba(255,255,255,.09),rgba(0,0,0,.16));left:28px;bottom:calc(34px + var(--safe-b));opacity:.55;transition:opacity .2s;display:grid;place-items:center}
.stick-base.active{opacity:1;border-color:rgba(255,122,26,.5)}
.stick-knob{width:44px;height:44px;border-radius:50%;background:radial-gradient(circle at 35% 30%,rgba(255,255,255,.55),rgba(255,122,26,.6));box-shadow:0 0 18px rgba(255,122,26,.35);will-change:transform}
.aim-hint{position:absolute;right:12%;bottom:35%;font-size:6px;letter-spacing:.2em;color:rgba(255,255,255,.2);writing-mode:vertical-rl}
.tbtn{position:absolute;pointer-events:auto;border-radius:50%;background:rgba(10,15,20,.55);border:1px solid rgba(255,255,255,.25);color:#e9f1f6;display:grid;place-items:center;touch-action:none;backdrop-filter:blur(4px);transition:background .1s,transform .08s;font-family:var(--font);z-index:16}
.tbtn:active,.tbtn.on{background:rgba(255,122,26,.32);border-color:rgba(255,170,80,.8);transform:scale(.93)}
.tbtn .icon{width:21px;height:21px;stroke-width:1.7}
.tbtn.fire{width:82px;height:82px;right:24px;bottom:calc(36px + var(--safe-b));background:radial-gradient(circle at 35% 30%,rgba(255,160,60,.4),rgba(180,50,0,.42));border:1px solid rgba(255,170,80,.65);box-shadow:0 0 24px rgba(255,110,20,.18)}
.tbtn.fire .icon{width:31px;height:31px;color:#ffd9ba}
.tbtn.fire span{position:absolute;bottom:12px;font-size:6px;letter-spacing:.16em;color:#ffd9ba}
.tbtn.ads{width:54px;height:54px;right:112px;bottom:calc(118px + var(--safe-b))}
.tbtn.jump{width:48px;height:48px;right:30px;bottom:calc(132px + var(--safe-b))}
.tbtn.crouch{width:44px;height:44px;right:112px;bottom:calc(40px + var(--safe-b))}
.tbtn.reload{width:44px;height:44px;right:110px;bottom:calc(76px + var(--safe-b))}
.tbtn.swap{width:44px;height:44px;right:164px;bottom:calc(40px + var(--safe-b))}
.tbtn.swap b{position:absolute;bottom:5px;font-size:5px;letter-spacing:.06em;font-weight:500;color:#b9c6d0}
.tbtn.interact{width:auto;height:38px;border-radius:19px;right:60px;bottom:calc(50% + var(--safe-b));padding:0 16px;font-size:8px;letter-spacing:.14em}
.tbtn.menu{width:40px;height:40px;left:16px;bottom:calc(216px + var(--safe-b));background:rgba(10,15,20,.6)}
.tbtn.menu .icon{width:17px;height:17px}
.tbtn.sprint{width:48px;height:48px;right:180px;bottom:calc(126px + var(--safe-b));font-size:6px;letter-spacing:.1em;color:#b8c6d0}
.tbtn.sprint.on{color:#fff;background:rgba(255,122,26,.25)}

/* ============================ RESULTS ============================ */
#results{z-index:70;display:grid;place-items:center;background:rgba(3,5,8,.6);backdrop-filter:blur(5px)}
.result-bg{position:absolute;inset:0;background:radial-gradient(ellipse at 50% 35%,rgba(255,110,20,.18),transparent 55%),linear-gradient(180deg,rgba(4,7,10,.4),rgba(4,7,10,.9));animation:fadeIn .4s ease}
.result-card{position:relative;width:min(640px,92vw);padding:30px;background:linear-gradient(160deg,rgba(16,23,30,.92),rgba(6,9,13,.94));border:1px solid var(--line);text-align:center;animation:resultIn .5s cubic-bezier(.2,.8,.2,1) both;box-shadow:0 40px 100px rgba(0,0,0,.6)}
.result-card::before{content:'';position:absolute;left:0;top:0;right:0;height:2px;background:linear-gradient(90deg,transparent,var(--orange),transparent)}
@keyframes resultIn{from{opacity:0;transform:translateY(24px) scale(.97)}to{opacity:1;transform:none}}
@keyframes fadeIn{from{opacity:0}to{opacity:1}}
.result-kicker{font-size:8px;letter-spacing:.36em;color:var(--orange);margin-bottom:4px}
.result-card h1{font-size:52px;font-style:italic;letter-spacing:.04em;line-height:1;background:linear-gradient(180deg,#fff,#ffc98f);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 4px 24px rgba(255,120,20,.3))}
#results.lose .result-card h1{background:linear-gradient(180deg,#fff,#ff8b8b);-webkit-background-clip:text;background-clip:text}
.result-place{display:flex;align-items:baseline;justify-content:center;gap:8px;margin:6px 0 18px}
.result-place b{font-family:var(--num);font-size:32px;color:var(--orange)}
.result-place span{font-size:7px;letter-spacing:.2em;color:var(--muted)}
.result-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;padding:14px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.result-stats div{display:flex;flex-direction:column;gap:2px}
.result-stats b{font-family:var(--num);font-size:23px;font-weight:700}
.result-stats span{font-size:6px;letter-spacing:.18em;color:var(--muted-2)}
.reward-row{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin:14px 0 20px}
.reward{display:flex;align-items:center;justify-content:center;gap:6px;padding:8px;background:rgba(255,255,255,.025);border:1px solid var(--line)}
.reward .icon{width:15px;height:15px;color:var(--gold)}
.reward b{font-family:var(--num);font-size:15px;color:#ffe1a8}
.reward span{font-size:6px;letter-spacing:.14em;color:var(--muted-2);margin-left:2px}
.result-actions{display:flex;gap:8px;justify-content:center}
.result-actions .solid-btn{padding:12px 22px}
.result-foot{margin-top:16px;font-size:6px;letter-spacing:.2em;color:#48545f}

/* ============================ MODAL / TOAST ============================ */
#modal{z-index:90;position:absolute;inset:0;display:grid;place-items:center}
.modal-backdrop{position:absolute;inset:0;background:rgba(3,5,8,.66);backdrop-filter:blur(5px)}
.modal-card{position:relative;width:min(560px,92vw);max-height:86vh;overflow-y:auto;padding:22px;animation:resultIn .28s ease both;scrollbar-width:thin}
.modal-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:16px}
.modal-head h2{font-size:22px;font-style:italic;letter-spacing:.06em}
.modal-head span{font-size:7px;letter-spacing:.18em;color:var(--muted-2);display:block;margin-top:2px}
.modal-close{width:28px;height:28px;display:grid;place-items:center;border:1px solid var(--line);color:var(--muted)}
.modal-close .icon{width:13px;height:13px}
.setting-row{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:10px 0;border-bottom:1px solid rgba(255,255,255,.05)}
.setting-row .set-name{font-size:9px;letter-spacing:.1em}
.setting-row .set-desc{font-size:6px;letter-spacing:.09em;color:var(--muted-2);margin-top:2px}
.setting-row input[type=range]{-webkit-appearance:none;appearance:none;width:150px;height:3px;background:rgba(255,255,255,.15);outline:none;accent-color:var(--orange)}
.setting-row input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:12px;height:12px;border-radius:50%;background:var(--orange);box-shadow:0 0 8px rgba(255,122,26,.6);cursor:pointer}
.seg{display:flex;border:1px solid var(--line);background:rgba(0,0,0,.25)}
.seg button{padding:5px 9px;font-size:6px;letter-spacing:.12em;color:var(--muted);border-right:1px solid var(--line)}
.seg button:last-child{border-right:0}
.seg button.active{background:rgba(255,122,26,.18);color:var(--orange)}
.toggle{width:34px;height:18px;border-radius:9px;background:rgba(255,255,255,.15);position:relative;transition:.2s;border:1px solid var(--line)}
.toggle::after{content:'';position:absolute;left:2px;top:2px;width:12px;height:12px;border-radius:50%;background:#8c99a4;transition:.2s}
.toggle.on{background:rgba(255,122,26,.3);border-color:rgba(255,122,26,.5)}
.toggle.on::after{left:17px;background:var(--orange);box-shadow:0 0 6px var(--orange)}
.settings-actions{display:flex;gap:8px;margin-top:16px}
#toast-wrap{position:absolute;left:50%;bottom:calc(8% + var(--safe-b));transform:translateX(-50%);z-index:95;display:flex;flex-direction:column;gap:5px;pointer-events:none;align-items:center}
.toast{padding:7px 14px;background:rgba(7,10,14,.9);border:1px solid var(--line);border-left:2px solid var(--orange);font-size:8px;letter-spacing:.12em;color:#d7e1e8;animation:toastIn 2.8s ease forwards;white-space:nowrap}
@keyframes toastIn{0%{opacity:0;transform:translateY(8px)}8%,82%{opacity:1;transform:none}100%{opacity:0;transform:translateY(-6px)}}

#lock-hint{position:absolute;left:50%;top:58%;transform:translate(-50%,-50%);z-index:18;display:flex;flex-direction:column;align-items:center;gap:5px;pointer-events:none;padding:12px 26px;background:rgba(5,9,13,.72);border:1px solid rgba(255,122,26,.32);border-left:2px solid var(--orange);backdrop-filter:blur(8px);animation:paneIn .4s ease both}
#lock-hint b{font-size:10px;letter-spacing:.22em;color:#f1f6f9}
#lock-hint span{font-size:6px;letter-spacing:.18em;color:#8595a2}
#lock-hint.hidden{display:none}

