startReload() {
  const w = this.weapon, def = w.def;
  if (this.reloadTimer > 0 || w.mag >= def.mag || w.reserve <= 0) return;
  this.reloadTimer = def.reload;
  audio.reload();
  this.game.hud?.startReload(def.reload);
}
finishReload() {
  const w = this.weapon, def = w.def;
  const need = def.mag - w.mag;
  const take = this.game.mode.infiniteAmmo ? need : Math.min(need, w.reserve);
  w.mag += take;
  if (!this.game.mode.infiniteAmmo) w.reserve -= take;
  this.game.hud?.updateAmmo();
}

jump() {
  if (!this.alive || this.mode !== 'fps') return;
  if (this.grounded) {
    this.vel.y = 6.7;
    this.grounded = false;
    this.landKick = 0.015;
  }
}

heal(amount = 50) {
  if (!this.alive) return false;
  if (this.medkits <= 0) return false;
  if (this.health >= 100) return false;
  this.medkits--;
  this.health = Math.min(100, this.health + amount);
  audio.heal();
  this.game.hud?.updateVitals();
  this.game.hud?.toast('MEDKIT USED', '+50 HEALTH');
  return true;
}
useShield(amount = 50) {
  if (!this.alive) return false;
  if (this.shields <= 0) return false;
  if (this.shield >= this.maxShield) return false;
  this.shields--;
  this.shield = Math.min(this.maxShield, this.shield + amount);
  audio.shield();
  this.game.hud?.updateVitals();
  this.game.hud?.toast('SHIELD CELL', '+50 ARMOR');
  return true;
}

