content.text:
Add ability HUD methods after updateAlive or end. Also cloak overlay. Need add `#cloak-overlay`? We can use HUD root class `cloaked`; add CSS. `setCloak(on) { this.root.classList.toggle('cloaked', on) }`.

Ability:
```
updateAbility(p) {
  if (!p) return;
  const a=p.operator.active;
  const ready = p.abilityCooldown<=0 && p.abilityLeft<=0;
  const btn=$('#ability-btn');
  btn.classList.toggle('ready', ready);
  btn.classList.toggle('active', p.abilityLeft>0);
  const cd = p.abilityLeft>0 ? Math.ceil(p.abilityLeft) : Math.ceil(p.abilityCooldown);
  $('#ability-cd').textContent = p.abilityLeft>0 ? Math.ceil(p.abilityLeft)+'S' : (p.abilityCooldown>0 ? Math.ceil(p.abilityCooldown)+'S' : 'READY');
  // ring sweep as conic-gradient via style --cd
  btn.style.setProperty('--cd', (p.abilityCooldown>0 ? (1 - p.abilityCooldown/a.cooldown) : 1)*360+'deg');
  $('#ability-state').textContent = p.abilityLeft>0 ? `ACTIVE · ${Math.ceil(p.abilityLeft)}S` : (p.abilityCooldown>0 ? `COOLDOWN · ${Math.ceil(p.abilityCooldown)}S` : `READY · ${a.cooldown}S COOLDOWN`);
  btn.classList.toggle('cooling', p.abilityCooldown>0);
  $('#ability-name').textContent = a.name;
  $('#ability-passive').textContent = p.operator.passive.name + ' · PASSIVE';
}
```
Maybe updating each frame is fine (DOM few).
`abilityActivated`, `abilityEnded`, `setCloak`.

Add click on quick buttons. Done.

Also HUD.update is called only from game, updateAbility each frame via player update; okay.

Let's add methods near bottom before showResults.

input.newString:
updateScore(a, b) {
  const el = $('#obj-score');
  if (el) el.innerHTML = `${a} <i>—</i> ${b}`;
}

updateAbility(p = this.game?.player) {
  if (!p) return;
  const a = p.operator.active;
  const btn = $('#ability-btn');
  if (!btn) return;
  const ready = p.abilityCooldown <= 0 && p.abilityLeft <= 0;
  const active = p.abilityLeft > 0;
  btn.classList.toggle('ready', ready);
  btn.classList.toggle('active', active);
  btn.classList.toggle('cooling', !ready && !active);
  btn.style.setProperty('--ab-color', p.operator.accent);
  btn.style.setProperty('--cd', (p.abilityCooldown > 0 ? (1 - p.abilityCooldown / a.cooldown) * 360 : 360) + 'deg');
  const cd = $('#ability-cd');
  if (cd) cd.textContent = active ? Math.ceil(p.abilityLeft) + 'S' : p.abilityCooldown > 0 ? Math.ceil(p.abilityCooldown) + 'S' : 'READY';
  const state = $('#ability-state');
  if (state) state.textContent = active ? `ACTIVE · ${Math.ceil(p.abilityLeft)}S` : p.abilityCooldown > 0 ? `COOLDOWN · ${Math.ceil(p.abilityCooldown)}S` : `READY · ${a.cooldown}S COOLDOWN`;
  const name = $('#ability-name');
  if (name) name.textContent = a.name;
  const passive = $('#ability-passive');
  if (passive) passive.textContent = p.operator.passive.name + ' · PASSIVE';
  const sweep = $('#ability-sweep');
  if (sweep) sweep.style.setProperty('--ab-color', p.operator.accent);
}

abilityActivated(a) {
  const btn = $('#ability-btn');
  btn?.classList.add('flash');
  setTimeout(() => btn?.classList.remove('flash'), 500);
}

abilityEnded(a) {
  this.toast(a.name + ' ENDED', 'RECHARGING');
}

setCloak(on) {
  this.root.classList.toggle('cloaked', !!on);
}

