renderCharacterItems replace whole function and add renderOperatorDetails. Let's write. Note item card `it.d` etc. For operator, need special card. Build conditional.

Detailed:
```
renderCharacterItems() {
 const host...
 if (cat==='operator') {
   host.innerHTML='';
   for const op of OPERATORS { btn class char-item op-card; innerHTML = `<span class="char-swatch operator-swatch" style="--op:${op.accent}"><span class="op-figure"><i></i></span><b>${op.role}</b></span><span class="char-name">${op.name}</span><span class="char-rarity" style=...>${op.rarity}</span><span class=eq-badge>...`;
   click ...
   }
   this.renderOperatorDetails();
   return;
 }
 $('#operator-details').innerHTML=''; ... normal.
}
```
`renderOperatorDetails` uses profile operator and shows:
- header: name role / active/passive
- stat rows: health, armor, speed, recoil, regen with values.
- active block with icon/key E and cooldown; passive block.
Maybe add a "preview" identity banner.

Use `op.stats.speed*100` etc. Use `Math.round(op.stats.health)`.
Need RARITY colors.

Let's replace function.

input.newString:
renderCharacterItems() {
  const host = $('#char-items');
  if (!host) return;
  const cat = this.charCategory;
  if (cat === 'operator') {
    const selected = this.profile.operator;
    host.innerHTML = '';
    for (const op of OPERATORS) {
      const btn = document.createElement('button');
      btn.className = 'char-item operator-card' + (op.id === selected ? ' active' : '');
      btn.innerHTML = `
        <span class="char-swatch operator-swatch" style="--op:${op.accent}">
          <span class="op-figure"><i></i></span>
          <b>${op.role}</b>
        </span>
        <span class="char-name">${op.name}</span>
        <span class="char-rarity" style="color:${RARITY[op.rarity] || '#9aa8b3'}">${op.rarity}</span>
        <span class="eq-badge"><svg class="icon"><use href="#i-check"/></svg></span>`;
      btn.addEventListener('click', () => {
        this.profile.operator = op.id;
        saveProfile(this.profile);
        this.applyOutfitCache();
        this.refreshLobbyAvatar();
        this.syncProfileUI();
        this.toast('OPERATOR EQUIPPED', op.name + ' · ' + op.role);
      });
      host.appendChild(btn);
    }
    this.renderOperatorDetails();
    return;
  }
  const det = $('#operator-details');
  if (det) det.innerHTML = '';
  let items;
  if (cat === 'outfit') items = OUTFITS.map(o => ({ id: o.id, name: o.name, rarity: o.rarity, a: o.top, b: o.vest, c: o.accent, d: o.pants, kind: 'outfit' }));
  else if (cat === 'helmet') items = HELMETS.map(o => ({ id: o.id, name: o.name, rarity: o.rarity, a: o.color === 'none' ? '#2c333c' : o.color, b: '#151b22', c: '#ff7a1a', kind: 'gear' }));
  else if (cat === 'backpack') items = BACKPACKS.map(o => ({ id: o.id, name: o.name, rarity: o.rarity, a: o.color === 'none' ? '#2c333c' : o.color, b: '#151b22', c: '#ff7a1a', kind: 'gear' }));
  else items = SKINS.map(o => ({ id: o.id, name: o.name, rarity: 'COMMON', a: o.color, b: o.color, c: '#ffffff', kind: 'skin' }));

  const selected = cat === 'outfit' ? this.profile.outfit
    : cat === 'helmet' ? this.profile.helmet
      : cat === 'backpack' ? this.profile.backpack
        : this.profile.skin;

  host.innerHTML = '';
  for (const it of items) {
    const btn = document.createElement('button');
    btn.className = 'char-item' + (it.id === selected ? ' active' : '');
    const swatch = it.kind === 'skin'
      ? `<span class="char-swatch" style="background:radial-gradient(circle at 50% 46%,${it.a},${it.a}99 32%,#0b1015 34%)"></span>`
      : `<span class="char-swatch" style="background:linear-gradient(150deg,${it.a}55,${it.b} 55%,#080c11)">
          <span class="suit" style="background:linear-gradient(180deg,${it.a},${it.d || it.b});border-top:2px solid ${it.c};border-bottom:2px solid ${it.c}55"></span>
        </span>`;
    btn.innerHTML = `${swatch}
      <span class="char-name">${it.name}</span>
      <span class="char-rarity" style="color:${RARITY[it.rarity] || '#9aa8b3'}">${it.rarity}</span>
      <span class="eq-badge"><svg class="icon"><use href="#i-check"/></svg></span>`;
    btn.addEventListener('click', () => {
      this.profile[cat] = it.id;
      saveProfile(this.profile);
      this.applyOutfitCache();
      this.refreshLobbyAvatar();
      this.syncProfileUI();
      this.toast('EQUIPPED', it.name);
    });
    host.appendChild(btn);
  }
}

renderOperatorDetails() {
  const host = $('#operator-details');
  if (!host) return;
  const op = operatorOf(this.profile.operator);
  const stat = (label, value, pct, color = 'var(--orange)') =>
    `<div class="op-stat"><span>${label}</span><i><b style="width:${clampPct(pct)}%;background:${color}"></b></i><em>${value}</em></div>`;
  host.innerHTML = `
    <div class="operator-details" style="--op:${op.accent}">
      <div class="op-head">
        <span class="op-emblem"><svg class="icon"><use href="#i-user"/></svg></span>
        <div><b>${op.name}</b><span>${op.role} · ${op.rarity}</span><i>${op.tagline}</i></div>
        <span class="op-live">ACTIVE OPERATOR</span>
      </div>
      <div class="op-body">
        <div class="op-stats">
          ${stat('HEALTH', op.stats.health, op.stats.health / 1.4, '#52e6a0')}
          ${stat('ARMOR', op.stats.armor, op.stats.armor / 0.7, '#4fd8ff')}
          ${stat('MOBILITY', Math.round(op.stats.speed * 100) + '%', (op.stats.speed - 0.85) / 0.3 * 100, '#ffd166')}
          ${stat('RECOIL', Math.round(op.stats.recoil * 100) + '%', (1.15 - op.stats.recoil) / 0.35 * 100, '#ff9d4a')}
        </div>
        <div class="op-skills">
          <div class="op-skill active-skill">
            <span class="skill-key">E</span>
            <div><b>${op.active.name}</b><span>ACTIVE · ${op.active.cooldown}S COOLDOWN</span><i>${op.active.desc}</i></div>
          </div>
          <div class="op-skill passive-skill">
            <span class="skill-key"><svg class="icon"><use href="#i-shield"/></svg></span>
            <div><b>${op.passive.name}</b><span>PASSIVE</span><i>${op.passive.desc}</i></div>
          </div>
        </div>
      </div>
    </div>`;
}

