for(const f of files){const s=fs.readFileSync(f,"utf8"); for(const m of s.matchAll(/\$\(.#([A-Za-z0-9_-]+).\)/g)){ if(!ids.has(m[1])) console.log(f,"MISSING #"+m[1]); }}
'

content.text:
13::root{
