233:.skin-dot.active{border-color:var(--orange);box-shadow:0 0 0 2px rgba(255,122,26,.22)}
234:.char-footer{display:flex;align-items:center;gap:8px;margin-top:13px;padding-top:11px;border-top:1px solid var(--line)}
