373:.dmg-num.crit{color:var(--orange);font-size:24px}
392:.vital-lvl{position:absolute;right:-5px;bottom:-5px;width:17px;height:17px;display:grid;place-items:center;background:var(--orange);color:#0b0e12;font-family:var(--num);font-size:8px;font-weight:700;font-style:normal;border-radius:50%}
394:.vital-name{display:flex;align-items:center;gap:6px;margin-bottom:5px}
395:.vital-name b{font-size:10px;letter-spacing:.11em}
396:.vital-name span{font-size:6px;letter-spacing:.13em;color:var(--teal);border:1px solid rgba(37,221,195,.3);padding:1px 4px}
406:.quick-slots{display:flex;gap:5px;margin-bottom:2px;position:relative;z-index:3}
407:.quick{width:42px;height:42px;position:relative;display:grid;place-items:center;background:rgba(8,12,17,.7);border:1px solid var(--line);color:#c1ced8;transition:.15s;pointer-events:auto;clip-path:polygon(0 0,100% 0,100% calc(100% - 7px),calc(100% - 7px) 100%,0 100%)}
408:.quick:hover{background:rgba(255,255,255,.1)}
